const TLB_ENTRIES = 512;
const PAGE_4K = 4 * 1024;
const PAGE_2M = 2 * 1024 * 1024;
const WORKING_SET = 1024 * 1024 * 1024; // 1 GB

const reach4k = TLB_ENTRIES * PAGE_4K;
const reach2m = TLB_ENTRIES * PAGE_2M;
const pages4k = WORKING_SET / PAGE_4K;
const pages2m = WORKING_SET / PAGE_2M;

console.log('TLB reach with 4KB pages:', (reach4k / (1024*1024)).toFixed(0), 'MB');
console.log('TLB reach with 2MB pages:', (reach2m / (1024*1024)).toFixed(0), 'MB');
console.log('Entries needed for 1GB (4KB):', pages4k);
console.log('Entries needed for 1GB (2MB):', pages2m);
console.log('Reduction factor:', pages4k / pages2m + 'x');
